    public async Task SaveChangesAsync()
    {
        if (isKhoaSoDiem) return;

        try
        {
            foreach (var maHs in modifiedStudents.ToList())
            {
                if (danhGiaCache.TryGetValue(maHs, out var d))
                {
                    await SaveDanhGiaNangLuc(d);
                }
            }
            modifiedStudents.Clear();
            ShowToast("Lưu thành công!", "success");
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
            throw;
        }
    }
    private void OnCommentChanged(DiemData.M_DanhGiaNangLucDTO d, string propertyName, string? newValue)
    {
        if (isKhoaSoDiem || !IsEditMode) return;

        // Cập nhật giá trị mới cho thuộc tính tương ứng
        switch (propertyName)
        {
            case nameof(DiemData.M_DanhGiaNangLucDTO.MaNxnlGk):
                d.MaNxnlGk = newValue ?? string.Empty;
                break;
            case nameof(DiemData.M_DanhGiaNangLucDTO.NxnlGk):
                d.NxnlGk = newValue ?? string.Empty;
                break;
            case nameof(DiemData.M_DanhGiaNangLucDTO.MaNxnlDacThuGk):
                d.MaNxnlDacThuGk = newValue ?? string.Empty;
                break;
            case nameof(DiemData.M_DanhGiaNangLucDTO.NxnlDacThuGk):
                d.NxnlDacThuGk = newValue ?? string.Empty;
                break;
            case nameof(DiemData.M_DanhGiaNangLucDTO.MaNxpcGk):
                d.MaNxpcGk = newValue ?? string.Empty;
                break;
            case nameof(DiemData.M_DanhGiaNangLucDTO.NxpcGk):
                d.NxpcGk = newValue ?? string.Empty;
                break;
        }

        // Đánh dấu học sinh này đã thay đổi
        modifiedStudents.Add(d.MaHocSinhSo);
    }
    public async Task DiscardChanges()
    {
        // Tải lại dữ liệu từ server
        await LoadDanhGiaNangLucData();
        modifiedStudents.Clear();
    }
    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrEmpty(SelectedLop))
        {
            await LoadLockStatus();
            await LoadHocSinhData();
            await LoadDanhGiaNangLucData();
            modifiedStudents.Clear(); // Reset khi chuyển lớp/kỳ
        }
    }

    #region Load dữ liệu
    private async Task LoadLevelFromStorage()
    {
        try
        {
            selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
            selectedTenCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevelText");
            if (string.IsNullOrEmpty(selectedCapHoc))
            {
                selectedCapHoc = "02";
                selectedTenCapHoc = "Cấp Tiểu học";
                await BrowserStorageService.SetItem(JS, "selectedLevel", selectedCapHoc);
                await BrowserStorageService.SetItem(JS, "selectedLevelText", selectedTenCapHoc);
            }
        }
        catch
        {
            selectedCapHoc = "02";
            selectedTenCapHoc = "Cấp Tiểu học";
        }
    }

    private async Task LoadLockStatus()
    {
        try
        {
            // Ở đây tạm thời dùng biến public, sau này có thể gọi service thực tế
            isKhoaSoDiem = PN_PublicVariables.IsKhoaSoDiem == "true";
        }
        catch { isKhoaSoDiem = false; }
    }

    private async Task OnKhoaSoDiemChanged(ChangeEventArgs e)
    {
        if (currentSession.Role != "Administrator") return;
        isKhoaSoDiem = (bool)e.Value;
        PN_ConfigHelper.UpdateKhoaSoDiem(isKhoaSoDiem);
        PN_PublicVariables.IsKhoaSoDiem = isKhoaSoDiem ? "true" : "false";
        ShowToast($"Sổ điểm đã {(isKhoaSoDiem ? "khóa" : "mở")}", isKhoaSoDiem ? "warning" : "success");
    }

    private async Task LoadHocSinhData()
    {
        try
        {

                hocSinhList = await TruongService.hGetHocSinhByLop(maTruongBo, SelectedLop, SelectedNamHoc);
                hocSinhList = hocSinhList.OrderBy(hs => hs, new HocSinhVietnameseComparer()).ToList();
           
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
        }
    }

    private async Task LoadDanhGiaNangLucData()
    {
        try
        {
            if (int.TryParse(SelectedLopId, out int lopId) && int.TryParse(SelectedHocKy, out int hocKy))
            {
                var namHoc = SelectedNamHoc;
                var danhGiaList = await DiemService.hGetDanhGiaNangLuc(lopId, hocKy, namHoc);
                danhGiaCache.Clear();
                foreach (var item in danhGiaList)
                {
                    danhGiaCache[item.MaHocSinhSo] = item;
                }
            }
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
        }
    }
    #endregion

    #region Lấy/Gán dữ liệu
    private DiemData.M_DanhGiaNangLucDTO GetDanhGia(string maHocSinh)
    {
        // 1. Tránh lỗi Dictionary nếu key bị null hoặc rỗng
        if (string.IsNullOrWhiteSpace(maHocSinh))
            return null; // Hoặc bạn có thể throw new ArgumentNullException(nameof(maHocSinh));

        // (Tùy chọn) Đảm bảo cache đã được khởi tạo
        // if (danhGiaCache == null) danhGiaCache = new Dictionary<string, DiemData.M_DanhGiaNangLucDTO>();

        if (danhGiaCache.TryGetValue(maHocSinh, out var d))
            return d;

        // 2. Xử lý parse an toàn với int.TryParse thay vì int.Parse
        int.TryParse(SelectedHocKy, out int hocKy);
        int.TryParse(SelectedLop, out int lopId);

        // 3. Xử lý an toàn chuỗi NamHoc trước khi Split và Parse
        int namHoc = 0;
        if (!string.IsNullOrWhiteSpace(SelectedNamHoc))
        {
            string namHocStr = SelectedNamHoc.Split('-')[0];
            int.TryParse(namHocStr, out namHoc);
        }

        var newItem = new DiemData.M_DanhGiaNangLucDTO
        {
            MaHocSinhSo = maHocSinh,
            HocSinhIdSo = maHocSinh,
            HocKy = hocKy,       // Nếu parse lỗi, giá trị sẽ là 0
            NamHoc = namHoc,     // Nếu parse lỗi, giá trị sẽ là 0
            LopId = lopId        // Nếu parse lỗi, giá trị sẽ là 0
        };

        danhGiaCache[maHocSinh] = newItem;
        return newItem;
    }

    private async Task SaveDanhGiaNangLuc(DiemData.M_DanhGiaNangLucDTO danhGia)
    {
        try
        {
            // Gán các giá trị hệ thống
            danhGia.MaSoGd = "79";
            danhGia.IdTruong = thData.truong?.IdTruongSo.ToString() ?? "0";
            danhGia.MaTruong = maTruongBo;
            danhGia.IdHocSinh = (await GetIdHocSinh(danhGia.MaHocSinhSo)).ToString();
            danhGia.IdPhongGd = "19475";
            danhGia.MaPhongGd = "778";

            var success = await DiemService.hUpsertDanhGiaNangLuc(danhGia);
            if (!success) throw new Exception("Lưu thất bại");
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
            throw;
        }
    }

    private async Task<long> GetIdHocSinh(string maHocSinh)
    {
        return hocSinhList.FirstOrDefault(h => h.MaHsSo == maHocSinh)?.HocSinhIdSo ?? 0;
    }
