    #region Bulk action
    private void ConfirmBulkAction(string type, string value)
    {
        bulkActionType = type;
        bulkActionValue = value;
        showConfirmModal = true;
    }

    private void CancelBulkAction() => showConfirmModal = false;

    private async Task ApplyConfirmedBulkAction()
    {
        showConfirmModal = false;
        if (isKhoaSoDiem || !IsEditMode) return;

        try
        {
            var fields = Array.Empty<string>();

            if (IsKhoi)
            {
                fields = bulkActionType switch
                {
                    "NLC" => new[] { "Tt22xNlTuChuGk", "Tt22xNlGthtGk", "Tt22xNlGqvdGk" },
                    "NLD" => new[] { "Tt22xNlNgonNguGk", "Tt22xNlTinhToanGk", "Tt22xNlKhoaHocGk", "Tt22xNlThamMiGk", "Tt22xNlTheChatGk" },
                    "PC" => new[] { "Tt22xPcYeuNuocGk", "Tt22xPcNhanAiGk", "Tt22xPcChamChiGk", "Tt22xPcTtGk", "Tt22xPcTnGk" },
                    _ => Array.Empty<string>()
                };
            }
            else
            {
                fields = bulkActionType switch
                {
                    "NLC" => new[] { "Tt22xNlTuChuGk", "Tt22xNlGthtGk", "Tt22xNlGqvdGk" },
                    "NLD" => new[] { "Tt22xNlNgonNguGk", "Tt22xNlTinhToanGk", "Tt22xNlKhoaHocGk", "Tt22xNlThamMiGk", "Tt22xNlTheChatGk", "Tt22xNlTinHocGk", "Tt22xNlCongNgheGk" },
                    "PC" => new[] { "Tt22xPcYeuNuocGk", "Tt22xPcNhanAiGk", "Tt22xPcChamChiGk", "Tt22xPcTtGk", "Tt22xPcTnGk" },
                    _ => Array.Empty<string>()
                };
            }

            foreach (var hs in hocSinhList)
            {
                var d = GetDanhGia(hs.MaHsSo);
                bool hasChange = false;

                foreach (var f in fields)
                {
                    switch (f)
                    {
                        case "Tt22xNlTuChuGk": if (d.Tt22xNlTuChuGk != bulkActionValue) { d.Tt22xNlTuChuGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlGthtGk": if (d.Tt22xNlGthtGk != bulkActionValue) { d.Tt22xNlGthtGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlGqvdGk": if (d.Tt22xNlGqvdGk != bulkActionValue) { d.Tt22xNlGqvdGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlNgonNguGk": if (d.Tt22xNlNgonNguGk != bulkActionValue) { d.Tt22xNlNgonNguGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlTinhToanGk": if (d.Tt22xNlTinhToanGk != bulkActionValue) { d.Tt22xNlTinhToanGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlKhoaHocGk": if (d.Tt22xNlKhoaHocGk != bulkActionValue) { d.Tt22xNlKhoaHocGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlThamMiGk": if (d.Tt22xNlThamMiGk != bulkActionValue) { d.Tt22xNlThamMiGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlTheChatGk": if (d.Tt22xNlTheChatGk != bulkActionValue) { d.Tt22xNlTheChatGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlCongNgheGk": if (d.Tt22xNlCongNgheGk != bulkActionValue) { d.Tt22xNlCongNgheGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlTinHocGk": if (d.Tt22xNlTinHocGk != bulkActionValue) { d.Tt22xNlTinHocGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xPcYeuNuocGk": if (d.Tt22xPcYeuNuocGk != bulkActionValue) { d.Tt22xPcYeuNuocGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xPcNhanAiGk": if (d.Tt22xPcNhanAiGk != bulkActionValue) { d.Tt22xPcNhanAiGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xPcChamChiGk": if (d.Tt22xPcChamChiGk != bulkActionValue) { d.Tt22xPcChamChiGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xPcTtGk": if (d.Tt22xPcTtGk != bulkActionValue) { d.Tt22xPcTtGk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xPcTnGk": if (d.Tt22xPcTnGk != bulkActionValue) { d.Tt22xPcTnGk = bulkActionValue; hasChange = true; } break;
                    }
                }

                if (hasChange)
                {
                    modifiedStudents.Add(d.MaHocSinhSo);
                }
            }

            ShowToast($"Đã áp dụng '{GetMucDatDuocText(bulkActionValue)}' cho {hocSinhList.Count} học sinh (chưa lưu)", "success");
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
        }
    }
