    #region File actions
    private void ShowDownloadModal() => showDownloadModal = true;
    private void CloseDownloadModal() => showDownloadModal = false;

    private async Task DownloadBangDiem()
    {
        if (string.IsNullOrEmpty(SelectedLop))
        {
            ShowToast("Vui lòng chọn lớp", "warning");
            return;
        }

        try
        {
            isDownloading = true;
            StateHasChanged();

            var request = new
            {
                ma_truong_bo = maTruongBo,
                lophoc_code = SelectedLop,
                ma_hocky = GetHocKyId(),
                nam_hoc = SelectedNamHoc,
                dot_danh_gia = "GK"
            };

            string apiUrl = TruongHocData.API_KetNoiSGD + "DownloadMauNLPC_C1";
            using var httpClient = new HttpClient();
            httpClient.Timeout = TimeSpan.FromMinutes(5);

            var response = await httpClient.PostAsJsonAsync(apiUrl, request);

            if (response.IsSuccessStatusCode)
            {
                var bytes = await response.Content.ReadAsByteArrayAsync();
                var fileName = $"Mau_DanhGiaNangLuc_GK_{SelectedNamHoc}_{GetTenLop()}.xlsx";
                using var streamRef = new DotNetStreamReference(new MemoryStream(bytes));
                await JS.InvokeVoidAsync("downloadFileFromStream", fileName, streamRef);
                ShowToast("Tải file thành công", "success");
                CloseDownloadModal();
            }
            else
            {
                var error = await response.Content.ReadAsStringAsync();
                ShowToast($"Lỗi tải file: {error}", "danger");
            }
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
        }
        finally
        {
            isDownloading = false;
            StateHasChanged();
        }
    }

    private void ShowUploadModal() => showUploadModal = true;
    private void CloseUploadModal()
    {
        showUploadModal = false;
        selectedFile = null;
    }

    private async Task TriggerFileUpload()
    {
        await JS.InvokeVoidAsync("triggerFileInput");
    }

    private async Task HandleFileUpload(InputFileChangeEventArgs e)
    {
        selectedFile = e.File;
        StateHasChanged();
    }

    private void RemoveSelectedFile() => selectedFile = null;

    private string GetFileSize(long bytes)
    {
        string[] sizes = { "B", "KB", "MB" };
        int order = 0;
        double len = bytes;
        while (len >= 1024 && order < sizes.Length - 1) { order++; len /= 1024; }
        return $"{len:0.##} {sizes[order]}";
    }

    private async Task UploadBangDiem()
    {
        if (selectedFile == null) return;

        try
        {
            isUploading = true;
            StateHasChanged();

            using var content = new MultipartFormDataContent();
            content.Add(new StringContent(maTruongBo ?? ""), "ma_truong_bo");
            content.Add(new StringContent(SelectedLop), "ma_lop");
            content.Add(new StringContent(GetHocKyId().ToString()), "ma_hocky");
            content.Add(new StringContent(SelectedNamHoc), "nam_hoc");
            content.Add(new StringContent("GK"), "dot_danh_gia");

            var fileStream = selectedFile.OpenReadStream(maxAllowedSize: 10 * 1024 * 1024);
            var fileContent = new StreamContent(fileStream);
            fileContent.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
            content.Add(fileContent, "file", selectedFile.Name);

            string apiUrl = TruongHocData.API_KetNoiSGD + "UploadNLPC_C1";
            using var httpClient = new HttpClient();
            httpClient.Timeout = TimeSpan.FromMinutes(10);

            var response = await httpClient.PostAsync(apiUrl, content);

            if (response.IsSuccessStatusCode)
            {
                ShowToast("Tải lên thành công! Đang cập nhật...", "success");
                await LoadDanhGiaNangLucData();
                CloseUploadModal();
            }
            else
            {
                var error = await response.Content.ReadAsStringAsync();
                ShowToast($"Lỗi: {error}", "danger");
            }
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
        }
        finally
        {
            isUploading = false;
        }
    }
