    #region Helpers
    private int GetHocKyId() => SelectedHocKy switch { "1" => 27, "2" => 28, _ => 27 };

    private string GetTenLop()
    {
        var lop = thData.danhSachLopList?.FirstOrDefault(l => l.IdLopBo.ToString() == SelectedLop);
        return lop?.TenLop ?? SelectedLop;
    }
    private string GetTenKhoi()
    {
        if (string.IsNullOrEmpty(SelectedKhoi)) return "Tất cả khối";
        var khoi = thData.danhSachKhoiList?.FirstOrDefault(k => k.MaKhoiBo.ToString() == SelectedKhoi);
        return khoi?.TenKhoi ?? SelectedKhoi;
    }

    private string GetTenHocKy() => SelectedHocKy == "1" ? "1" : "2";

    private string FormatNgaySinh(DateTime? date) => date?.ToString("dd/MM/yyyy") ?? "";

    private string GetMucDatDuocText(string value) => value switch
    {
        "T" => "Hoàn thành (T)",
        "Đ" => "Đạt (Đ)",
        "C" => "Chưa hoàn thành (C)",
        "" => "Xóa",
        _ => value
    };

    private void ShowToast(string msg, string type)
    {
        toastMessage = msg;
        toastClass = $"alert-{type}";
        StateHasChanged();
        Task.Delay(3000).ContinueWith(_ => InvokeAsync(() => { toastMessage = ""; StateHasChanged(); }));
    }

    private void ClearToast() => toastMessage = "";
    #endregion

    #region Comparer
    private class HocSinhVietnameseComparer : IComparer<HocSinhDTO>
    {
        private readonly CompareInfo cmp = CultureInfo.GetCultureInfo("vi-VN").CompareInfo;
        public int Compare(HocSinhDTO? x, HocSinhDTO? y)
        {
            if (x == null || y == null) return 0;
            return cmp.Compare(x.HoTen, y.HoTen, CompareOptions.StringSort);
        }
    }
    #endregion

    private class ApiResponse_NopDiem
    {
        public int status_code { get; set; }
        public string error_code { get; set; } = "";
        public string message { get; set; } = "";
    }

